ALTER TABLE public.items ADD COLUMN IF NOT EXISTS search_document tsvector;
CREATE OR REPLACE FUNCTION public.item_search_document() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.search_document:=to_tsvector('simple',coalesce(NEW.title_en,'')||' '||coalesce(NEW.title_ka,'')||' '||coalesce(NEW.creator,'')||' '||coalesce(NEW.description_en,'')||' '||array_to_string(NEW.keywords,' ')); RETURN NEW; END $$;
CREATE TRIGGER item_search_document_trigger BEFORE INSERT OR UPDATE OF title_en,title_ka,creator,description_en,keywords ON public.items FOR EACH ROW EXECUTE FUNCTION public.item_search_document();
UPDATE public.items SET search_document=to_tsvector('simple',coalesce(title_en,'')||' '||coalesce(title_ka,'')||' '||coalesce(creator,'')||' '||coalesce(description_en,'')||' '||array_to_string(keywords,' '));
CREATE INDEX items_search_document_idx ON public.items USING gin(search_document);
CREATE OR REPLACE FUNCTION public.ask_rank(intent jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH reference_items AS (SELECT i.* FROM items i WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(intent->'similar_to','[]')) t WHERE lower(i.title_en)=lower(t) OR lower(i.original_title)=lower(t)) LIMIT 5),wanted AS (SELECT x->>'facet' facet,x->>'value' value FROM jsonb_array_elements(coalesce(intent->'traits','[]')) x),candidates AS (SELECT i.* FROM items i JOIN profiles p ON p.id=auth.uid() WHERE (coalesce(intent->>'media_type','either')='either' OR i.media_type=intent->>'media_type') AND (NOT coalesce((intent->>'georgian_only')::boolean,false) OR i.is_georgian) AND (intent->>'min_year' IS NULL OR i.year>=(intent->>'min_year')::integer) AND (intent->>'max_year' IS NULL OR i.year<=(intent->>'max_year')::integer) AND (intent->>'max_minutes' IS NULL OR (i.media_type='film' AND i.runtime_minutes<=(intent->>'max_minutes')::integer)) AND (intent->>'max_pages' IS NULL OR (i.media_type='book' AND i.page_count<=(intent->>'max_pages')::integer)) AND NOT i.genres && p.avoided_genres AND NOT i.genres && ARRAY(SELECT jsonb_array_elements_text(coalesce(intent->'excluded_genres','[]'))) AND NOT EXISTS(SELECT 1 FROM swipes s WHERE s.user_id=auth.uid() AND s.item_id=i.id) AND NOT EXISTS(SELECT 1 FROM logs l WHERE l.user_id=auth.uid() AND l.item_id=i.id AND l.status='seen') AND NOT EXISTS(SELECT 1 FROM reference_items s WHERE s.id=i.id) AND NOT EXISTS(SELECT 1 FROM wanted w WHERE NOT EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=i.id AND f.facet=w.facet AND f.value=w.value)) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(intent->'genres','[]')) g WHERE NOT g=ANY(i.genres)) AND (jsonb_array_length(coalesce(intent->'creators','[]'))=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(intent->'creators') c WHERE i.creator ILIKE '%'||c||'%'))),relevant AS (SELECT c.*,(SELECT count(*) FROM wanted)*1.0+jsonb_array_length(coalesce(intent->'genres','[]'))*1.0+(SELECT count(*) FROM jsonb_array_elements_text(coalesce(intent->'keywords','[]')) k WHERE k=ANY(c.keywords))*0.4+(SELECT count(*) FROM item_facets f WHERE f.item_id=c.id AND EXISTS(SELECT 1 FROM item_facets rf JOIN reference_items ri ON ri.id=rf.item_id WHERE rf.facet=f.facet AND rf.value=f.value))*0.3+(SELECT count(*) FROM reference_items ri WHERE ri.genres && c.genres)*0.2+CASE WHEN jsonb_array_length(coalesce(intent->'creators','[]'))>0 THEN 1 ELSE 0 END+ts_rank(c.search_document,websearch_to_tsquery('simple',coalesce(intent->>'query','')))+CASE WHEN intent->>'max_minutes' IS NOT NULL OR intent->>'max_pages' IS NOT NULL OR coalesce((intent->>'georgian_only')::boolean,false) THEN 0.2 ELSE 0 END AS relevance FROM candidates c),rated AS (SELECT r.*,coalesce((SELECT avg(CASE t.stance WHEN 'loves' THEN 1 WHEN 'leans_toward' THEN 0.5 WHEN 'leans_away' THEN -0.5 WHEN 'avoids' THEN -1 ELSE 0 END*t.importance) FROM item_facets f JOIN user_taste t ON t.user_id=auth.uid() AND t.media_type=r.media_type AND t.facet=f.facet AND t.value=f.value WHERE f.item_id=r.id),0) taste FROM relevant r WHERE r.relevance>=0.15),picked AS (SELECT * FROM rated ORDER BY 0.7*relevance+0.3*taste DESC,popularity DESC,id LIMIT 5)
SELECT coalesce(jsonb_agg(jsonb_build_object('item',to_jsonb(picked)-'search_document'-'relevance'-'taste','reason','Matches your request: '||concat_ws(', ',NULLIF((SELECT string_agg(replace(value,'_',' '),', ') FROM wanted),''),NULLIF(array_to_string(ARRAY(SELECT jsonb_array_elements_text(coalesce(intent->'genres','[]'))),', '),''),CASE WHEN runtime_minutes IS NOT NULL THEN runtime_minutes||' min' WHEN page_count IS NOT NULL THEN page_count||' pages' END,CASE WHEN jsonb_array_length(coalesce(intent->'similar_to','[]'))>0 THEN 'shares traits with '||array_to_string(ARRAY(SELECT jsonb_array_elements_text(intent->'similar_to')),', ') END),'score',0.7*relevance+0.3*taste)),'[]') FROM picked;
$$;
REVOKE ALL ON FUNCTION public.ask_rank(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ask_rank(jsonb) TO authenticated;